645|      if (ret == Z_OK)
646|      {
647|         png_uint_32 lzsize = chunklength - prefix_size;
648|
649|         ret = png_inflate(png_ptr, png_ptr->chunk_name, 1/*finish*/,
650|             /* input: */ png_ptr->read_buffer + prefix_size, &lzsize,
651|             /* output: */ NULL, newlength);
