152|         case PNG_NUMBER_FORMAT_fixed:
153|            /* Needs five digits (the fraction) */
154|            mincount = 5;
155|            if (output != 0 || number % 10 != 0)
156|            {
157|               *--end = digits[number % 10];
158|               output = 1;
159|            }
160|            number /= 10;
161|            break;
162|
163|         case PNG_NUMBER_FORMAT_02u:
164|            /* Expects at least 2 digits. */
165|            mincount = 2;
166|            /* FALLTHROUGH */
